import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import { Page } from './types';

const DEFAULT_LAYOUT = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{{title}}</title>
</head>
<body>
  {{{body}}}
</body>
</html>`;

const DEFAULT_PAGE_TEMPLATE = `<h1>{{title}}</h1>
{{#if date}}
<p>Date: {{date}}</p>
{{/if}}
{{#if tags.length}}
<p>Tags: {{#each tags}}{{this}}{{#unless @last}}, {{/unless}}{{/each}}</p>
{{/if}}
{{{content}}}
<p><a href="index.html">Back to index</a></p>`;

const DEFAULT_INDEX_TEMPLATE = `<h1>Site Index</h1>
<ul>
{{#each pages}}
<li><a href="{{slug}}.html">{{title}}</a></li>
{{/each}}
</ul>`;

const DEFAULT_LAYOUT_NAME = 'default';
const DEFAULT_PAGE_TEMPLATE_NAME = 'page';
const DEFAULT_INDEX_TEMPLATE_NAME = 'index';

interface TemplateCache {
  [name: string]: Handlebars.TemplateDelegate;
}

export class TemplateEngine {
  private templatesDir: string;
  private compiled: TemplateCache = {};

  constructor(templatesDir: string) {
    this.templatesDir = path.resolve(templatesDir);
    this.loadPartials();
    this.registerBuiltins();
  }

  private registerBuiltins(): void {
    this.compiled[`__layout__${DEFAULT_LAYOUT_NAME}`] = Handlebars.compile(DEFAULT_LAYOUT);
    this.compiled[`__page__${DEFAULT_PAGE_TEMPLATE_NAME}`] = Handlebars.compile(DEFAULT_PAGE_TEMPLATE);
    this.compiled[`__page__${DEFAULT_INDEX_TEMPLATE_NAME}`] = Handlebars.compile(DEFAULT_INDEX_TEMPLATE);
  }

  private loadPartials(): void {
    const partialsDir = path.join(this.templatesDir, 'partials');
    if (!fs.existsSync(partialsDir)) return;

    const entries = fs.readdirSync(partialsDir, { withFileTypes: true });
    for (const entry of entries) {
      if (!entry.isFile() || !entry.name.endsWith('.hbs')) continue;

      const partialPath = path.join(partialsDir, entry.name);
      const partialName = entry.name.replace(/\.hbs$/, '');
      const source = fs.readFileSync(partialPath, 'utf-8');
      Handlebars.registerPartial(partialName, source);
    }
  }

  private loadTemplate(kind: 'layout' | 'page' | 'partial', name: string): Handlebars.TemplateDelegate {
    const cacheKey = `__${kind}__${name}`;
    if (this.compiled[cacheKey]) {
      return this.compiled[cacheKey];
    }

    const subdir = kind === 'layout' ? 'layouts' : '';
    const dir = subdir ? path.join(this.templatesDir, subdir) : this.templatesDir;
    const filePath = path.join(dir, `${name}.hbs`);

    if (!fs.existsSync(filePath)) {
      throw new Error(`Template not found: ${filePath}`);
    }

    const source = fs.readFileSync(filePath, 'utf-8');
    const compiled = Handlebars.compile(source);
    this.compiled[cacheKey] = compiled;
    return compiled;
  }

  private getLayout(name?: string): Handlebars.TemplateDelegate {
    const layoutName = name || DEFAULT_LAYOUT_NAME;
    try {
      return this.loadTemplate('layout', layoutName);
    } catch {
      return this.compiled[`__layout__${DEFAULT_LAYOUT_NAME}`];
    }
  }

  private getPageTemplate(name?: string): Handlebars.TemplateDelegate {
    const templateName = name || DEFAULT_PAGE_TEMPLATE_NAME;
    try {
      return this.loadTemplate('page', templateName);
    } catch {
      return this.compiled[`__page__${DEFAULT_PAGE_TEMPLATE_NAME}`];
    }
  }

  renderPage(page: Page): string {
    const template = this.getPageTemplate(page.frontmatter.template);
    return template({
      title: page.frontmatter.title,
      date: page.frontmatter.date,
      tags: page.frontmatter.tags,
      content: page.html,
      slug: page.slug,
    });
  }

  renderIndex(pages: Page[]): string {
    let template: Handlebars.TemplateDelegate;
    try {
      template = this.loadTemplate('page', DEFAULT_INDEX_TEMPLATE_NAME);
    } catch {
      template = this.compiled[`__page__${DEFAULT_INDEX_TEMPLATE_NAME}`];
    }
    return template({ pages });
  }

  renderLayout(title: string, body: string, layoutName?: string): string {
    const layout = this.getLayout(layoutName);
    return layout({ title, body });
  }
}

